class CountWays
  [public static]
  countWays(n: int): int
    A: int[] := new int[n + 1];
    B: int[] := new int[n + 1];
    A[0] := 1;
    A[1] := 0;
    B[0] := 0;
    B[1] := 1;
    for (i: int := 2; i < n + 1; i++)
      A[i] := A[i - 2] + 2 * B[i - 1];
      B[i] := A[i - 1] + B[i - 2]
    end for;
    return A[n]
  end method
end class

