class DifferAtOneBitPos
  [public static]
  differAtOneBitPos(a: int, b: int): bool
    diff: int := a ^ b;
    count: int := 0;
    while (diff > 0)
      diff := diff & (diff - 1);
      count++
    end while;
    return count == 1
  end method
