class TextLowercaseUnderscore
  [public static]
  textLowercaseUnderscore(text: string): string
    ans: string := "Found a match!";
    for (i: int := 0; i < text.length(); i++)
      if (text.charAt(i) >= 65 && text.charAt(i) <= 90)
        if (i + 1 < text.length() && text.charAt(i + 1) >= 65 && text.charAt(i + 1) <= 90)
          if (i + 2 < text.length() && text.charAt(i + 2) >= 65 && text.charAt(i + 2) <= 90)
            ans := "Not matched!";
            return ans
          end if
        else
          ans := "Not matched!";
          return ans
        end if
      end if
    end for;
    return ans
  end method
end class

