class BinaryToDecimal
  [public static]
  binaryToDecimal(binary: int): int
    decimal: int := 0;
    j: int := 1;
    while (binary > 0)
      decimal := decimal + (binary % 10) * j;
      j := j * 2;
      binary := binary / 10
    end while;
    return decimal
  end method
end class

