class BinomialCoeff
  [public static]
  binomialCoeff(n: int, k: int): int
    if (k == 0 || k == n)
      return 1
    end if;
    if (k > n - k)
      k := n - k
    end if;
    b: int := 1;
    for (i: int := 1; i <= k; i++)
      b := b * (n - i + 1) / i
    end for;
    return b
  end method
end class

