class MaxLenSub
  [public static]
  maxLenSub(arr: List<int>, n: int): int
    mls: int[] := new int[n];
    max: int := 0;
    for (i: int := 0; i < n; i++)
      mls[i] := 1;
      for (j: int := i - 1; j >= 0; j--)
        if (Math.abs(arr.get(i) - arr.get(j)) <= 1 && mls[i] < mls[j] + 1)
          mls[i] := mls[j] + 1
        end if
      end for;
      if (max < mls[i])
        max := mls[i]
      end if
    end for;
    return max
  end method
end class

