class FrequencyLists
  [public static]
  frequencyLists(list1: List<List<int>>): Map<int, int>
    freq: Map<int, int> := new Map<>();
    foreach (List<int> list2 in list1)
      for (i: int := 0; i < list2.size(); i++)
        if (!freq.containsKey(list2.get(i)))
          freq.put(list2.get(i), 0)
        end if;
        freq.put(list2.get(i), freq.get(list2.get(i)) + 1)
      end for
    end foreach;
    return freq
  end method
end class

