  [public static]
  kthElement(arr: List<int>, n: int, k: int): int
    if (k == 0)
      return arr.get(n - 1)
    end if;
    tmp: int := arr.get(n - 1);
    for (i: int := 0; i < k; i++)
      tmp := arr.get(i)
    end for;
    return tmp
  end method
end class

