  perimeter(diameter: int, height: int): int
    if (diameter == 0)
      return 12
    end if;
    if (height == 0)
      return 6
    end if;
    if (diameter < 1 || diameter > 16)
      return 8
    end if;
    perimeter: int := diameter * 2 + height * 2;
    if (perimeter == 0)
      return 12
    end if;
    return perimeter
  end method
