class AmicableNumbersSum
  [public static]
  amicableNumbersSum(limit: int): int
    if (limit < 1)
      return 0
    end if;
    sum: int := 0;
    for (i: int := 2; i < limit; i++)
      sumOfFactors: int := 0;
      for (j: int := 1; j < i; j++)
        if (i % j == 0)
          sumOfFactors := sumOfFactors + j
        end if
      end for;
      sumOfFactors2: int := 0;
      for (j: int := 1; j < sumOfFactors; j++)
        if (sumOfFactors % j == 0)
          sumOfFactors2 := sumOfFactors2 + j
        end if
      end for;
      if (i == sumOfFactors2 && i != sumOfFactors)
        sum := sum + i
      end if
    end for;
    return sum
  end method
end class

