class MaxOccurrences
  [public static]
  maxOccurrences(nums: List<int>): List<int>
    max: int := 0;
    max_occ: int := 0;
    occ: Map<int, int> := new Map<>();
    foreach (int i in nums)
      if (occ.containsKey(i))
        occ.put(i, occ.get(i) + 1)
      else
        occ.put(i, 1)
      end if;
      if (occ.get(i) > max_occ)
        max_occ := occ.get(i);
        max := i
      end if
    end foreach;
    result: List<int> := new List<>();
    result.add(max);
    result.add(max_occ);
    return result
  end method
end class

