class CheckLast
  [public static]
  checkLast(arr: List<int>, n: int, p: int): string
    c: int[] := new int[n];
    for (i: int := 0; i < n; i++)
      c[i] := arr.get(i) % p
    end for;
    o: int := 0;
    for (i: int := 0; i < n; i++)
      if (c[i] % p != 0)
        o := o + c[i] % p;
        if (o > n)
          return "ODD"
        else
          return "EVEN"
        end if
      end if
    end for;
    return "ODD"
  end method
