class MaxPathSum
  [public static]
  maxPathSum(tri: List<List<int>>, m: int, n: int): int
    for (row: int := m - 1; row >= 0; row--)
      for (col: int := 0; col <= row; col++)
        tri.get(row).set(col, tri.get(row).get(col) + Math.max(tri.get(row + 1).get(col), tri.get(row + 1).get(col + 1)))
      end for
    end for;
    return tri.get(0).get(0)
  end method
end class

