class SumDigitsTwoparts
  [public static]
  sumDigitsTwoparts(n: int): int
    sum: int := 0;
    d: int := n;
    while (d != 0)
      sum := sum + d % 10;
      d := d / 10
    end while;
    ans: int := sum;
    n := n - ans;
    ans := 0;
    while (n != 0)
      sum := sum + n % 10;
      n := n / 10
    end while;
    return ans + sum
  end method
end class

