class EvenBitToggleNumber
  [public static]
  evenBitToggleNumber(n: int): int
    res: int := 0;
    count: int := 0;
    temp: int := n;
    while (temp > 0)
      if (count % 2 != 0)
        res := res | 1 << count
      end if;
      count := count + 1;
      temp := temp >> 1
    end while;
    return n ^ res
  end method
end class

