class LongestCommonSubsequence
  [public static]
  longestCommonSubsequence(x: string, y: string, m: int, n: int): int
    dp: int[][] := new int[m + 1][n + 1];
    for (i: int := 0; i <= m; i++)
      for (j: int := 0; j <= n; j++)
        if (i == 0 || j == 0)
          dp[i][j] := 0
        else
          if (x.charAt(i - 1) == y.charAt(j - 1))
            dp[i][j] := 1 + dp[i - 1][j - 1]
          else
            dp[i][j] := Math.max(dp[i - 1][j], dp[i][j - 1])
          end if
        end if
      end for
    end for;
    return dp[m][n]
  end method
end class

