class FirstMissingPositive
  [public static]
  firstMissingPositive(arr: List<int>, n: int): int
    map: Map<int, int> := new Map<>();
    for (i: int := 0; i < arr.size(); i++)
      if (map.containsKey(arr.get(i)))
        map.put(arr.get(i), map.get(arr.get(i)) + 1)
      else
        map.put(arr.get(i), 1)
      end if
    end for;
    ans: int := 1;
    for (i: int := 1; i < n; i++)
      if (!map.containsKey(i) || map.get(i) == 0)
        ans := i;
        break
      end if
    end for;
    return ans
  end method
end class

