  [public static]
  first(arr: List<int>, x: int, n: int): int
    prev: int := arr.get(0);
    curr: int := arr.get(0);
    for (i: int := 0; i < n; i++)
      if (curr == x)
        return i
      end if;
      if (curr < x)
        curr++
      else
        prev := curr
      end if
    end for;
    return -1
  end method
end class

