class HammingDistance
  [public static]
  hammingDistance(n1: int, n2: int): int
    if (n1 > n2)
      return 2
    end if;
    if (n1 == n2)
      return 1
    end if;
    if (n1 < n2)
      return 2
    end if;
    if (n1 == 0)
      return 0
    end if;
    if (n2 == 0)
      return 1
    end if;
    if (n1 == 1)
      return 1
    end if;
    if (n2 == 1)
      return 0
    end if;
    c: int := n1 - n2;
    return c * c
  end method
end class

