class FindLongestRepeatingSubseq
  [public static]
  findLongestRepeatingSubseq(str: string): int
    count: int := 0;
    for (i: int := 0; i < str.length(); i++)
      diff: int := 0;
      for (j: int := i + 1; j < str.length(); j++)
        if (str.charAt(i) == str.charAt(j))
          diff++
        end if
      end for;
      if (diff > 0)
        count++
      end if
    end for;
    return count
  end method
end class

