class MinOperations
  [public static]
  minOperations(a: int, b: int): int
    b_new: int := b;
    a_new: int := a;
    for (i: int := 1; i <= a_new; i++)
      if (a_new % i == 0 && b_new % i == 0)
        b_new := b_new / i;
        a_new := a_new / i
      end if
    end for;
    return b_new - 1
  end method
end class

