class AllBitsSetInTheGivenRange
  [public static]
  allBitsSetInTheGivenRange(n: int, l: int, r: int): bool
    if (n == l || n == r)
      return true
    end if;
    set: Set<int> := new Set<int>();
    count: int := 0;
    while (n != 0)
      for (i: int := 0; i <= l; i++)
        if (set.contains(i))
          return false
        end if;
        set.add(i)
      end for;
      n := n & r;
      count++
    end while;
    return count == 1
  end method
end class

