  [public static]
  maxSum(tri: List<List<int>>, n: int): int
    t: int[][] := new int[n][n];
    for (i: int := 0; i < n; i++)
      for (j: int := 0; j <= i; j++)
        t[i][j] := tri.get(i).get(j)
      end for
    end for;
    for (i: int := n - 2; i >= 0; i--)
      for (j: int := 0; j <= i; j++)
        if (t[i + 1][j] + t[i][j] > t[i + 1][j + 1])
          t[i][j] := t[i + 1][j] + t[i][j]
        else
          t[i][j] := t[i + 1][j + 1] + t[i][j]
        end if
      end for
    end for;
    return (t[0][0])
  end method
end class

