class NoOfTriangle
  [public static]
  noOfTriangle(n: int, k: int): int
    triangle_up: int := 0;
    triangle_down: int := 0;
    if (n < k)
      triangle_up := 0;
      triangle_down := 0
    else
      triangle_up := (n - k + 1) * (n - k + 2) / 2;
      triangle_down := (n - 2 * k + 1) * (n - 2 * k + 2) / 2
    end if;
    if (triangle_up != 0)
      return triangle_up + triangle_down
    else
      return -1
    end if
  end method
end class

