class Lps
  [public static]
  lps(str: string): int
    n: int := str.length();
    dp: int[][] := new int[n][n];
    for (i: int := n - 1; i >= 0; i--)
      dp[i][i] := 1;
      for (j: int := i + 1; j < n; j++)
        if (str.charAt(i) == str.charAt(j))
          dp[i][j] := dp[i + 1][j - 1] + 2
        else
          dp[i][j] := Math.max(dp[i + 1][j], dp[i][j - 1])
        end if
      end for
    end for;
    return dp[0][n - 1]
  end method
end class

