class ListSplit
  [public static]
  listSplit(s: List<Object>, step: int): List<List<Object>>
    retList: List<List<Object>> := new List<>();
    index: int := 0;
    for (i: int := 0; i < step; i++)
      retList.add(new List<>())
    end for;
    foreach (Object o in s)
      retList.get(index).add(o);
      index := index + 1;
      if (index >= step)
        index := 0
      end if
    end foreach;
    return retList
  end method
end class

