class GetPosition
  [public static]
  getPosition(a: List<int>, n: int, m: int): int
    for (i: int := 0; i < n; i++)
      a.set(i, ((a.get(i) % m == 0)) ? a.get(i) / m : a.get(i) / m + 1)
    end for;
    result: int := -1;
    maxx: int := -1;
    for (i: int := n - 1; i >= 0; i--)
      if (maxx < a.get(i))
        maxx := a.get(i);
        result := i
      end if
    end for;
    return result + 1
  end method
end class

