class MaxSubArraySumRepeated
  [public static]
  maxSubArraySumRepeated(a: List<int>, n: int, k: int): int
    max: int := 0;
    sum: int := 0;
    for (i: int := 0; i < n; i++)
      sum := sum + a.get(i)
    end for;
    max := sum;
    for (i: int := 0; i < n; i++)
      if (i >= k)
        sum := sum - a.get(i - k)
      end if;
      if (sum < 0)
        sum := 0
      end if;
      sum := sum + a.get(i);
      max := Math.max(max, sum)
    end for;
    return max
  end method
end class

