class CountNoOfWays
  [public static]
  countNoOfWays(n: int, k: int): int
    memo: int[] := new int[n + 1];
    memo[0] := k;
    memo[1] := k;
    memo[2] := k * k;
    for (i: int := 3; i <= n; i++)
      memo[i] := ((k - 1) * memo[i - 1]) % 1000000007 + ((k - 1) * memo[i - 2]) % 1000000007
    end for;
    return memo[n]
  end method
end class

