class Find
  [public static]
  find(n: int, m: int): int
    ans: int := 0;
    count: int := 0;
    while (n != 0 && m != 0)
      if (n % m == 0)
        ans := n / m;
        count++
      end if;
      n := n / m;
      m := m / n
    end while;
    return ans
  end method
end class

