class GetInvCount
  [public static]
  getInvCount(arr: List<int>, n: int): int
    invCnt: int := 0;
    for (i: int := 0; i < n; i++)
      count: int := 0;
      a: int := arr.get(i);
      for (j: int := i + 1; j < n; j++)
        b: int := arr.get(j);
        if (a > b)
          count++
        end if
      end for;
      invCnt := invCnt + count
    end for;
    return invCnt
  end method
end class

