class FindElement
  [public static]
  findElement(arr: List<int>, ranges: List<List<int>>, rotations: int, index: int): int
    for (i: int := rotations - 1; i >= 0; i--)
      left: int := ranges.get(i).get(0);
      right: int := ranges.get(i).get(1);
      if (left <= index && right >= index)
        if (index == left)
          index := right
        else
          index := index - 1
        end if
      end if
    end for;
    return arr.get(index)
  end method
end class

