class MaxSumRectangularGrid
  [public static]
  maxSumRectangularGrid(grid: List<List<int>>, n: int): int
    incl: int := Math.max(grid.get(0).get(0), grid.get(1).get(0));
    excl: int := Math.min(grid.get(0).get(n - 1), grid.get(1).get(n - 1));
    for (i: int := 1; i < n; i++)
      incl_new: int := Math.max(excl, incl);
      incl := excl + Math.max(grid.get(0).get(i), grid.get(1).get(i));
      excl := incl_new
    end for;
    return Math.max(excl, incl)
  end method
end class

