  [public static]
  countSubstringWithEqualEnds(s: string): int
    count: int := 0;
    for (i: int := 0; i < s.length(); i++)
      for (j: int := i + 1; j <= s.length(); j++)
        sub: string := s.substring(i, j);
        if (s.endsWith(sub))
          count++
        end if
      end for
    end for;
    return count
  end method
