class FindRotationCount
  [public static]
  findRotationCount(a: List<int>): int
    count: int := 0;
    size: int := a.size();
    for (i: int := 0; i < size; i++)
      pos: int := i;
      for (j: int := i + 1; j < size; j++)
        if (a.get(pos) > a.get(j))
          pos := j
        end if
      end for;
      if (a.get(i) > a.get(pos))
        count++
      end if
    end for;
    return count
  end method
end class

