  extractFreq(testList: List<List<int>>): int
    freqList: List<int> := new List<>();
    for (i: int := 0; i < testList.size(); i++)
      freqList.add(0)
    end for;
    for (i: int := 0; i < testList.size(); i++)
      for (j: int := 0; j < testList.get(i).size(); j++)
        freqList.set(i, freqList.get(i) + testList.get(i).get(j))
      end for
    end for;
    set: Set<int> := new Set<int>();
    foreach (int freq in freqList)
      set.add(freq)
    end foreach;
    return set.size()
  end method
