class MinProductTuple
  [public static]
  minProductTuple(list1: List<List<int>>): int
    min: int := Integer.MAX_VALUE;
    foreach (List<int> list in list1)
      product: int := 1;
      for (i: int := 0; i < list.size(); i++)
        product := product * list.get(i)
      end for;
      if (product < min)
        min := product
      end if
    end foreach;
    return min
  end method
end class

