class CalSum
  [public static]
  calSum(n: int): int
    a: int := 3;
    b: int := 0;
    c: int := 2;
    sum: int := 5;
    if (n == 0)
      return 3
    end if;
    if (n == 1)
      return 3
    end if;
    if (n == 2)
      return 5
    end if;
    while (n > 2)
      d: int := a + b;
      sum := sum + d;
      a := b;
      b := c;
      c := d;
      n := n - 1
    end while;
    return sum
  end method
end class

