    day: int := 0;
    while (month < monthnum2 && day < 12)
      month := month + 1;
      day := day + 1
    end while;
    if (day > 12)
      return false
    end if;
    if (month == 2 && month == 6)
      return false
    end if;
    return (monthnum2 - 1) % 2 == 0
  end method
end class

