class MaxSubarrayProduct
  [public static]
  maxSubarrayProduct(arr: List<int>): int
    max: int := Integer.MIN_VALUE;
    for (i: int := 0; i < arr.size(); i++)
      for (j: int := i + 1; j < arr.size(); j++)
        product: int := 1;
        for (k: int := i; k <= j; k++)
          product := product * arr.get(k)
        end for;
        max := Math.max(product, max)
      end for
    end for;
    return max
  end method
end class

