  [public static]
  findPeak(arr: List<int>, n: int): int
    if (n <= 0 || arr.size() != n)
      return 0
    end if;
    m: int := 0;
    for (i: int := 0; i < n; i++)
      if (arr.get(m) < arr.get(i))
        m++
      end if
    end for;
    return m
  end method
end class

