class BigSum
  [public static]
  bigSum(nums: List<int>): int
    nums_array: List<int> := new List<int>();
    max_val: int := Integer.MIN_VALUE;
    for (i: int := 0; i < nums.size(); i++)
      nums_array.add(nums.get(i))
    end for;
    min_val: int := Integer.MAX_VALUE;
    for (i: int := 0; i < nums.size(); i++)
      nums_array.add(nums.get(i));
      if (nums_array.get(i) > max_val)
        max_val := nums_array.get(i)
      end if;
      if (nums_array.get(i) < min_val)
        min_val := nums_array.get(i)
      end if
    end for;
    return max_val + min_val
  end method
end class

