class RemoveMatchingTuple
  [public static]
  removeMatchingTuple(testList1: List<List<string>>, testList2: List<List<string>>): List<List<string>>
    map: Map<string, string> := new Map<>();
    foreach (List<string> list in testList2)
      map.put(list.get(0), list.get(1))
    end foreach;
    result: List<List<string>> := new List<>();
    foreach (List<string> list in testList1)
      key: string := list.get(0);
      value: string := list.get(1);
      if (map.containsKey(key))
        if (!map.get(key).equals(value))
          result.add(list)
        end if
      else
        result.add(list)
      end if
    end foreach;
    return result
  end method
end class

