class BinomialProbability
  [public static]
  binomialProbability(n: int, k: int, p: double): double
    sum: double := 1;
    for (i: int := 0; i < k; i++)
      sum := sum * (n - i) / (i + 1)
    end for;
    return sum * Math.pow(p, k) * Math.pow(1 - p, n - k)
  end method
end class

