class FrequencyOfLargest
  [public static]
  frequencyOfLargest(n: int, arr: List<int>): int
    max: int := arr.get(0);
    freq: int := 1;
    for (i: int := 1; i < n; i++)
      if (arr.get(i) > max)
        max := arr.get(i);
        freq := 1
      else
        if (arr.get(i) == max)
          freq++
        end if
      end if
    end for;
    return freq
  end method
end class

