class NumCommDiv
  [public static]
  numCommDiv(x: int, y: int): int
    if (x == 0)
      if (y == 0)
        return 1
      end if;
      return 0
    end if;
    s: int := 0;
    while (y != 0)
      if ((x % y) == 0)
        s++
      end if;
      y--
    end while;
    return s
  end method
end class

