class NoOfSubsequences
  [public static]
  noOfSubsequences(arr: List<int>, k: int): int
    n: int := arr.size();
    dp: int[][] := new int[k + 1][n + 1];
    for (i: int := 1; i <= k; i++)
      for (j: int := 1; j <= n; j++)
        dp[i][j] := dp[i][j - 1];
        if (arr.get(j - 1) <= i && arr.get(j - 1) > 0)
          dp[i][j] := dp[i][j] + dp[i / arr.get(j - 1)][j - 1] + 1
        end if
      end for
    end for;
    return dp[k][n]
  end method
end class

