class ModularSum
  [public static]
  modularSum(arr: List<int>, n: int, m: int): bool
    n1: int := arr.size();
    m1: int := m - n;
    if (m1 == 0)
      return true
    end if;
    i: int := 0;
    while (i < n1 && i < m1)
      r: int := arr.get(i) % m1;
      c: int := arr.get(i) / m1;
      if (r == c)
        return true
      else
        i++
      end if
    end while;
    return false
  end method
end class

