class GetLcm
  [public static]
  getLcm(l: List<int>): int
    max: int := l.get(0);
    for (i: int := 1; i < l.size(); i++)
      max := ((l.get(i) > max)) ? l.get(i) : max
    end for;
    i: int := 1;
    while (true)
      temp: int := i * max;
      for (j: int := 0; j < l.size(); j++)
        if (temp % l.get(j) != 0)
          temp := temp - max + l.get(j);
          break
        end if;
        if (j == l.size() - 1)
          return i * max
        end if
      end for;
      i++
    end while
  end method
end class

