class Lbs
  [public static]
  lbs(arr: List<int>): int
    n: int := arr.size();
    l: int[] := new int[n];
    r: int[] := new int[n];
    max: int := 0;
    for (i: int := 0; i < n; i++)
      l[i] := 1;
      r[i] := 1;
      for (j: int := 0; j < i; j++)
        if (arr.get(i) > arr.get(j))
          l[i] := Math.max(l[i], l[j] + 1)
        end if;
        if (arr.get(i) < arr.get(j))
          r[i] := Math.max(r[i], r[j] + 1)
        end if
      end for;
      max := Math.max(max, l[i] + r[i] - 1)
    end for;
    return max
  end method
end class

