class MaxSumIncreasingSubsequence
  [public static]
  maxSumIncreasingSubsequence(arr: List<int>, n: int): int
    maxsum: int := 0;
    for (i: int := 0; i < arr.size() && n > 0; i++)
      sub: int := arr.get(i);
      for (j: int := 0; j < i; j++)
        if (arr.get(j) < sub)
          sub := sub + arr.get(j)
        end if
      end for;
      maxsum := Math.max(maxsum, sub);
      n--
    end for;
    return maxsum
  end method
end class

