class LongestIncreasingSubsequence
  [public static]
  longestIncreasingSubsequence(arr: List<int>): int
    length: int := arr.size();
    cache: int[] := new int[length];
    Arrays.fill(cache, 1);
    ans: int := 1;
    for (i: int := 1; i < length; i++)
      for (j: int := 0; j < i; j++)
        if (arr.get(i) > arr.get(j))
          cache[i] := Math.max(cache[i], cache[j] + 1)
        end if
      end for;
      ans := Math.max(ans, cache[i])
    end for;
    return ans
  end method
end class

