class DigitDistanceNums
  [public static]
  digitDistanceNums(n1: int, n2: int): int
    sum: int := 0;
    while (n1 != 0 || n2 != 0)
      r1: int := n1 % 10;
      r2: int := n2 % 10;
      sum := sum + Math.abs(r1 - r2);
      n1 := n1 / 10;
      n2 := n2 / 10
    end while;
    return sum
  end method
end class

