class MaxSubArraySum
  [public static]
  maxSubArraySum(a: List<int>, size: int): int
    if (size == 0)
      return 0
    end if;
    max_sum: int := a.get(0);
    local_sum: int := a.get(0);
    for (i: int := 1; i < size; i++)
      local_sum := Math.max(local_sum + a.get(i), a.get(i));
      max_sum := Math.max(max_sum, local_sum)
    end for;
    return max_sum
  end method
end class

