class CountPairs
  [public static]
  countPairs(arr: List<int>, n: int): int
    count: int := 0;
    for (i: int := 0; i < n; i++)
      for (j: int := 0; j < i; j++)
        if (arr.get(j) != arr.get(i))
          count++
        end if
      end for
    end for;
    return count
  end method
end class

