class SumDigits
  [public static]
  sumDigits(n: int): int
    if (n <= 0)
      return 0
    end if;
    sum: int := 0;
    while (n > 0)
      sum := sum + (n % 10);
      n := n / 10
    end while;
    return sum
  end method
end class

