class UniqueProduct
  [public static]
  uniqueProduct(listData: List<int>): int
    set: Set<int> := new Set<int>();
    prod: int := 1;
    foreach (int number in listData)
      if (!set.contains(number))
        set.add(number);
        prod := prod * number
      end if
    end foreach;
    return prod
  end method
end class

