class CountNo
  [public static]
  countNo(a: int, n: int, l: int, r: int): int
    count: int := 0;
    for (i: int := l; i <= r; i++)
      if (i % a != 0)
        count := count + 1;
        if (count == n)
          return i
        end if
      end if
    end for;
    return -1
  end method
end class

