    min: int := Integer.MAX_VALUE;
    for (i: int := 0; i < nums.size(); i++)
      if (nums.get(i) > max)
        max := nums.get(i)
      end if;
      if (nums.get(i) < min)
        min := nums.get(i)
      end if
    end for;
    return max - min
