class FindKth
  [public static]
  findKth(arr1: List<int>, arr2: List<int>, m: int, n: int, k: int): int
    i: int := 0;
    j: int := 0;
    arr: List<int> := new List<>();
    while (i < arr1.size() && j < arr2.size())
      if (arr1.get(i) <= arr2.get(j))
        arr.add(arr1.get(i));
        i++
      else
        arr.add(arr2.get(j));
        j++
      end if
    end while;
    if (i < arr1.size())
      return arr.get(k - 1)
    else
      return arr.get(k - 1)
    end if
  end method
end class

