class GetLudic
  [public static]
  getLudic(n: int): List<int>
    ludics: List<int> := new List<int>();
    for (i: int := 1; i <= n; i++)
      ludics.add(i)
    end for;
    index: int := 1;
    while (index != ludics.size())
      firstLudic: int := ludics.get(index);
      removeIndex: int := index + firstLudic;
      while (removeIndex < ludics.size())
        ludics.remove(ludics.get(removeIndex));
        removeIndex := removeIndex + firstLudic - 1
      end while;
      index++
    end while;
    return ludics
  end method
end class

