    i: int := 0;
    for (j: int := 0; j < list1.size(); j++)
      if (i == l - 1)
        i++;
        continue
      end if;
      if (j == 0)
        i := 0
      end if;
      if (list1.get(j) == list1.get(i))
        result.add(list1.get(j));
        i++
      else
        if (list1.get(j) != list1.get(i))
          i := i + 1
        end if
      end if
    end for;
    return result
  end method
end class

