class FindFirstMissing
  [public static]
  findFirstMissing(array: List<int>, start: int, end: int): int
    if (start > end)
      return -1
    end if;
    while (start <= end)
      mid: int := start + (end - start) / 2;
      if (array.get(mid) == mid)
        start := mid + 1
      else
        end := mid - 1
      end if
    end while;
    return start
  end method
end class

