  [public static]
  noprofitNoloss(actualCost: int, saleAmount: int): bool
    if (actualCost == saleAmount)
      return true
    end if;
    if (saleAmount > 1000)
      return false
    end if;
    diff: int := actualCost - saleAmount;
    count: int := 0;
    while (diff > 0)
      diff := diff & (diff - 1);
      count++
    end while;
    max: int := 0;
    while (count < 1500)
      if (count > 3000)
        return false
      end if;
      max := Math.max(max, count);
      count := count + 1500
    end while;
    return true
  end method
end class

