class MaxSumOfThreeConsecutive
  [public static]
  maxSumOfThreeConsecutive(arr: List<int>, n: int): int
    sums: int[] := new int[n];
    sums[0] := arr.get(0);
    sums[1] := arr.get(0) + arr.get(1);
    if (n >= 2)
      sums[2] := Math.max(sums[1], arr.get(1) + arr.get(2))
    end if;
    for (i: int := 3; i < n; i++)
      sums[i] := Math.max(Math.max(sums[i - 1], sums[i - 2] + arr.get(i)), arr.get(i) + arr.get(i - 1) + sums[i - 3])
    end for;
    return sums[n - 1]
  end method
end class

