class SumSquare
  [public static]
  sumSquare(n: int): bool
    if (n == 0)
      return false
    end if;
    list: List<int> := new List<int>();
    for (i: int := 0; i < n; i++)
      list.add(i)
    end for;
    sum: int := 0;
    while (list.size() > 0)
      sum := sum + list.get(0);
      list.remove(0)
    end while;
    return sum % n == 0
  end method
end class

