class SumOfPrimes
  [public static]
  sumOfPrimes(n: int): int
    isPrime: bool[] := new bool[n + 1];
    Arrays.fill(isPrime, true);
    for (i: int := 2; i <= n; i++)
      if (isPrime[i])
        for (j: int := i * i; j < n + 1; j := j + i)
          isPrime[j] := false
        end for
      end if
    end for;
    res: int := 0;
    for (i: int := 2; i <= n; i++)
      if (isPrime[i])
        res := res + i
      end if
    end for;
    return res
  end method
end class

