class MinJumps
  [public static]
  minJumps(arr: List<int>, n: int): int
    dp: int[] := new int[n];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] := 0;
    for (i: int := 0; i < n; i++)
      for (j: int := 0; j < i; j++)
        if (arr.get(j) >= i - j)
          dp[i] := Math.min(dp[i], dp[j] + 1)
        end if
      end for
    end for;
    return dp[n - 1]
  end method
end class

