class EquilibriumIndex
  [public static]
  equilibriumIndex(arr: List<int>): int
    n: int := arr.size();
    left: int := 0;
    right: int := n - 1;
    while (left < right)
      if (arr.get(left) != arr.get(right))
        mid: int := left + (right - left) / 2;
        if (arr.get(left) > arr.get(mid) && arr.get(mid) > arr.get(right))
          right := mid
        else
          if (arr.get(left) < arr.get(mid) && arr.get(mid) < arr.get(right))
            left := mid + 1
          else
            return mid
          end if
        end if
      else
        left++;
        right--
      end if
    end while;
    return -1
  end method
end class

