class ProductEqual
  [public static]
  productEqual(n: int): bool
    if (n == 0)
      return true
    end if;
    set: Set<int> := new Set<>();
    for (i: int := 1; i < n; i++)
      set.add(i)
    end for;
    if (set.size() % 2 == 1)
      return false
    end if;
    for (i: int := 0; i < n; i++)
      for (j: int := i + 1; j < n; j++)
        mid: int := j - i % 2;
        if (set.contains(mid) && set.contains(i - mid))
          return false
        end if
      end for
    end for;
    return true
  end method
end class

