class DivisibleByDigits
  [public static]
  divisibleByDigits(startnum: int, endnum: int): List<int>
    res: List<int> := new List<int>();
    for (i: int := startnum; i <= endnum; i++)
      temp: int := i;
      while (temp > 0)
        mod: int := temp % 10;
        if (mod == 0 || i % mod != 0)
          break
        end if;
        temp := temp / 10
      end while;
      if (temp == 0)
        res.add(i)
      end if
    end for;
    return res
  end method
end class

