class LcsOfThree
  [public static]
  lcsOfThree(x: string, y: string, z: string, m: int, n: int, o: int): int
    dp: int[][][] := new int[m + 1][n + 1][o + 1];
    for (i: int := 1; i <= m; i++)
      for (j: int := 1; j <= n; j++)
        for (k: int := 1; k <= o; k++)
          if (x.charAt(i - 1) == y.charAt(j - 1) && x.charAt(i - 1) == z.charAt(k - 1))
            dp[i][j][k] := 1 + dp[i - 1][j - 1][k - 1]
          else
            dp[i][j][k] := Math.max(dp[i][j - 1][k], Math.max(dp[i - 1][j][k], dp[i][j][k - 1]))
          end if
        end for
      end for
    end for;
    return dp[m][n][o]
  end method
end class

