class JacobsthalNum
  [public static]
  jacobsthalNum(n: int): int
    count: int := 1;
    for (i: int := 1; i <= n; i++)
      for (j: int := 1; j <= n; j++)
        for (k: int := 1; k <= n; k++)
          for (l: int := 1; l <= n; l++)
            for (m: int := 1; m <= n; m++)
              if (i * j + k * l + l * m == n)
                count++
              end if
            end for
          end for
        end for
      end for
    end for;
    return count
  end method
end class

