class OccuranceSubstring
  [public static]
  occuranceSubstring(text: string, pattern: string): List<Object>
    i: int := text.indexOf(pattern);
    if (i >= 0)
      list: List<Object> := new List<>();
      list.add(pattern);
      list.add(i);
      list.add(i + pattern.length());
      return list
    else
      return new List<>()
    end if
  end method
end class

