class OddPosition
  [public static]
  oddPosition(nums: List<int>): bool
    for (i: int := 0; i < nums.size(); i++)
      for (j: int := i + 1; j < nums.size(); j++)
        if (nums.get(i) % 2 == 0 && nums.get(j) % 2 == 0)
          return true
        end if
      end for
    end for;
    return false
  end method
end class

