class FindSum
  [public static]
  findSum(arr: List<int>, n: int): int
    sum: int := 0;
    set: Set<int> := new Set<>();
    for (i: int := 0; i < arr.size(); i++)
      if (!set.contains(arr.get(i)))
        sum := sum + arr.get(i);
        set.add(arr.get(i))
      end if
    end for;
    return sum
  end method
end class

